function minimumOperations(nums) {
  const evenCount = new Map();
  const oddCount = new Map();
  for (let i = 0; i < nums.length; i++) {
    const count = i % 2 === 0 ? evenCount : oddCount;
    count.set(nums[i], (count.get(nums[i]) || 0) + 1);
  }
  const topTwo = (count) => {
    let first = { value: 0, freq: 0 };
    let second = { value: 0, freq: 0 };
    for (const [value, freq] of count) {
      if (freq > first.freq) {
        second = first;
        first = { value, freq };
      } else if (freq > second.freq) {
        second = { value, freq };
      }
    }
    return [first, second];
  };
  const [evenFirst, evenSecond] = topTwo(evenCount);
  const [oddFirst, oddSecond] = topTwo(oddCount);
  if (evenFirst.value !== oddFirst.value) {
    return nums.length - evenFirst.freq - oddFirst.freq;
  }
  const keep = Math.max(evenFirst.freq + oddSecond.freq, evenSecond.freq + oddFirst.freq);
  return nums.length - keep;
}

