function minimumOperations(nums) {
  // Try every pair of target values: each value already present, plus two fresh values nobody uses.
  const fresh = Math.max(...nums) + 1;
  const candidates = [...new Set(nums), fresh, fresh + 1];
  let best = Infinity;
  for (const a of candidates) {
    for (const b of candidates) {
      if (a === b) continue;
      let changes = 0;
      nums.forEach((v, i) => { if (v !== (i % 2 === 0 ? a : b)) changes++; });
      best = Math.min(best, changes);
    }
  }
  return best;
}

