function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 9);
  const mode = Math.floor(rand() * 3);
  if (mode === 0) {
    // Few distinct values, so the most common even and odd values often clash.
    const k = 1 + Math.floor(rand() * 4);
    return [Array.from({ length: n }, () => 1 + Math.floor(rand() * k))];
  }
  if (mode === 1) {
    // Mostly one shared value everywhere, with a little noise.
    const main = 1 + Math.floor(rand() * 100000);
    const pool = size === 'large' ? 50 : 3;
    return [Array.from({ length: n }, () => (rand() < 0.6 ? main : 1 + Math.floor(rand() * pool)))];
  }
  const top = size === 'large' ? 100000 : 6;
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
